import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";var i=JSON.parse(`{"title":"安装（历史存档）","description":"","frontmatter":{},"headers":[],"relativePath":"archive/install.md","filePath":"archive/install.md","lastUpdated":1792942748000}`),a={name:`archive/install.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="安装-历史存档" tabindex="-1">安装（历史存档） <a class="header-anchor" href="#安装-历史存档" aria-label="Permalink to “安装（历史存档）”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">存档说明</p><p>本页只收录已从 Magisk 官方 <code>install.md</code> 移除的章节。当前安装说明请见<a href="./../install.html">安装</a>。</p><p>华为章节最后一次出现在 <a href="https://github.com/topjohnwu/Magisk/blob/11c882380f321c9a83264d9b41b759306508b8a6/docs/install.md#huawei" target="_blank" rel="noreferrer">2021-04-21 的 install.md</a>，并在 <a href="https://github.com/topjohnwu/Magisk/commit/4f73534837bda59fd58ca010fe25d3d66556883e" target="_blank" rel="noreferrer">2021-05-12 的更新</a> 中被移除。以下为中文翻译，原文请以链接版本为准。</p></div><h2 id="华为" tabindex="-1">华为 <a class="header-anchor" href="#华为" aria-label="Permalink to “华为”">​</a></h2><p>Magisk 不再正式支持现代华为设备，因为其设备上的 bootloader 无法通过官方途径解锁，更重要的是它们不遵循标准的 Android 分区方案。以下只是一些一般性指导。</p><p>使用麒麟（Kirin）处理器的华为设备与大多数常见设备的分区方式不同。Magisk 通常安装在设备的 <code>boot</code> 分区中，但华为设备没有该分区。</p><p>通常请按照<a href="./../install.html#修补映像">修补映像</a>的步骤操作，但与原说明有以下区别：</p><ul><li>下载固件 zip 后（可以在 <a href="http://pro-teammt.ru/firmware-database/" target="_blank" rel="noreferrer">Huawei Firmware Database</a> 中找到许多固件），您需要使用 <a href="https://forum.xda-developers.com/showthread.php?t=2433454" target="_blank" rel="noreferrer">Huawei Update Extractor</a>（仅限 Windows！）从 zip 中的 <code>UPDATE.APP</code> 提取映像。</li><li>关于修补映像： <ul><li>如果您的设备有启动 ramdisk，请修补 <code>RAMDISK.img</code>，而不是 <code>boot.img</code></li><li>如果您的设备<strong>没有</strong>启动 ramdisk，请修补 <code>RECOVERY_RAMDIS.img</code>（这不是拼写错误），而不是 <code>recovery.img</code></li></ul></li><li>使用 <code>fastboot</code> 刷回映像时： <ul><li>如果修补的是 <code>RAMDISK.img</code>，请使用命令 <code>fastboot flash ramdisk magisk_patched.img</code> 刷入</li><li>如果修补的是 <code>RECOVERY_RAMDIS.img</code>，请使用命令 <code>fastboot flash recovery_ramdisk magisk_patched.img</code> 刷入</li></ul></li></ul><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h2><ul><li><a href="https://github.com/topjohnwu/Magisk/blob/11c882380f321c9a83264d9b41b759306508b8a6/docs/install.md" target="_blank" rel="noreferrer">Magisk 安装说明（2021-04-21 最后一版）</a>（官方历史版本）</li><li><a href="https://github.com/topjohnwu/Magisk/commit/4f73534837bda59fd58ca010fe25d3d66556883e" target="_blank" rel="noreferrer">移除华为章节的提交（2021-05-12）</a>（官方历史版本）</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};